export const envelope = [56, 34, 56];

export default function build(api) {
  const [W, H, D] = api.size;
  const grid = new Map();

  function put(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid.set((x << 16) | (y << 8) | z, block);
    }
  }

  function get(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid.get((x << 16) | (y << 8) | z) || null;
    }
    return null;
  }

  // --- Ground Query Helper ---
  function getGroundY(x, z) {
    const rawH = api.heightAt(x, z);
    return Math.max(0, Math.min(12, 6 + Math.round(rawH)));
  }

  // ==========================================
  // 1. GROUND CROP CIRCLE & TRANSMUTATION ZONE
  // ==========================================
  const beamCenterX = 28;
  const beamCenterZ = 26;

  for (let z = 0; z < D; z++) {
    for (let x = 0; x < W; x++) {
      const dist = Math.hypot(x - beamCenterX, z - beamCenterZ);
      if (dist <= 11) {
        const yg = getGroundY(x, z);

        // Fill foundation below ground
        for (let y = 0; y < yg; y++) {
          put(x, y, z, "minecraft:deepslate_tiles");
        }

        // Alien glyph / crop circle patterns on surface
        if (dist <= 2.2) {
          put(x, yg, z, "minecraft:sea_lantern");
        } else if (dist <= 3.8) {
          put(x, yg, z, "minecraft:crying_obsidian");
        } else if (dist <= 5.2) {
          put(x, yg, z, "minecraft:sculk_catalyst");
        } else if (dist <= 7.0) {
          // Concentric rune ring
          const ringMod = Math.floor(dist * 2) % 2;
          put(x, yg, z, ringMod === 0 ? "minecraft:crying_obsidian" : "minecraft:sculk");
        } else if (dist <= 9.0) {
          // Radial spikes
          const angle = Math.atan2(z - beamCenterZ, x - beamCenterX);
          const isSpoke = Math.cos(angle * 8) > 0.6;
          if (isSpoke) {
            put(x, yg, z, "minecraft:crying_obsidian");
          } else {
            put(x, yg, z, "minecraft:polished_blackstone");
          }
        } else {
          // Outer perimeter etched ring
          put(x, yg, z, "minecraft:polished_blackstone_bricks");
        }
      }
    }
  }

  // ==========================================
  // 2. THREE GRAVITY STABILIZER ANCHOR PADS
  // ==========================================
  const anchorPoints = [
    [28, 8],   // Front
    [12, 42],  // Rear Left
    [44, 42]   // Rear Right
  ];

  for (const [ax, az] of anchorPoints) {
    for (let dx = -3; dx <= 3; dx++) {
      for (let dz = -3; dz <= 3; dz++) {
        const d = Math.hypot(dx, dz);
        if (d <= 3.2) {
          const px = ax + dx;
          const pz = az + dz;
          const yg = getGroundY(px, pz);

          for (let y = 0; y < yg; y++) {
            put(px, y, pz, "minecraft:deepslate_tiles");
          }

          if (d <= 1.2) {
            put(px, yg, pz, "minecraft:sea_lantern");
          } else if (d <= 2.2) {
            put(px, yg, pz, "minecraft:crying_obsidian");
          } else {
            put(px, yg, pz, "minecraft:polished_blackstone");
          }
        }
      }
    }
  }

  // ==========================================
  // 3. CENTRAL TRACTOR BEAM (GROUND TO HULL)
  // ==========================================
  for (let z = 22; z <= 30; z++) {
    for (let x = 24; x <= 32; x++) {
      const d = Math.hypot(x - beamCenterX, z - beamCenterZ);
      const yg = getGroundY(x, z);

      for (let y = yg + 1; y <= 16; y++) {
        if (d <= 1.2) {
          // Inner high-energy column
          if (y % 4 === 0) {
            put(x, y, z, "minecraft:beacon");
          } else if (y % 2 === 0) {
            put(x, y, z, "minecraft:sea_lantern");
          } else {
            put(x, y, z, "minecraft:cyan_stained_glass");
          }
        } else if (d <= 2.4) {
          put(x, y, z, "minecraft:cyan_stained_glass");
        } else if (d <= 3.5) {
          // Spiral containment flux
          const angle = Math.atan2(z - beamCenterZ, x - beamCenterX);
          const spiral = Math.sin(angle * 2 + y * 0.7);
          if (spiral > 0.45) {
            put(x, y, z, "minecraft:crying_obsidian");
          } else if (spiral > 0.0) {
            put(x, y, z, "minecraft:light_blue_stained_glass");
          }
        }
      }
    }
  }

  // Levitating abducted farm debris inside beam
  const debrisList = [
    [28, 26, 0.2, "minecraft:sculk_catalyst"],
    [27, 26, 0.4, "minecraft:hay_block"],
    [29, 25, 0.6, "minecraft:oak_planks"],
    [28, 27, 0.75, "minecraft:crying_obsidian"],
    [27, 27, 0.9, "minecraft:sea_lantern"]
  ];

  for (const [dx, dz, fraction, blk] of debrisList) {
    const yg = getGroundY(dx, dz);
    const yTarget = Math.round(yg + (15 - yg) * fraction);
    if (yTarget < 16) {
      put(dx, yTarget, dz, blk);
    }
  }

  // ==========================================
  // 4. THREE STABILIZER TETHER COLUMNS
  // ==========================================
  for (const [ax, az] of anchorPoints) {
    const yg = getGroundY(ax, az);
    for (let y = yg + 1; y <= 17; y++) {
      // Core conduit
      put(ax, y, az, (y % 3 === 0) ? "minecraft:sea_lantern" : "minecraft:crying_obsidian");

      // Outer stabilizing struts
      put(ax + 1, y, az, "minecraft:polished_blackstone_wall");
      put(ax - 1, y, az, "minecraft:polished_blackstone_wall");
      put(ax, y, az + 1, "minecraft:polished_blackstone_wall");
      put(ax, y, az - 1, "minecraft:polished_blackstone_wall");

      // Plasma nodes
      if (y === yg + 3 || y === 15) {
        put(ax + 1, y, az + 1, "minecraft:crying_obsidian");
        put(ax - 1, y, az - 1, "minecraft:crying_obsidian");
        put(ax + 1, y, az - 1, "minecraft:crying_obsidian");
        put(ax - 1, y, az + 1, "minecraft:crying_obsidian");
      }
    }
  }

  // ==========================================
  // 5. MOTHERSHIP CARAPACE (DELTA DREADNOUGHT)
  // ==========================================
  function getHalfWidth(z) {
    if (z < 3) return 0;
    if (z <= 48) {
      return 23 * ((z - 3) / 45);
    }
    if (z <= 51) {
      return 23 - (z - 48) * 3;
    }
    return 0;
  }

  function getRearZ(dx) {
    if (dx < 14) {
      return 37 + (11 / 23) * dx;
    }
    return 43.7 + ((dx - 14) / 9) * 6.3;
  }

  for (let z = 3; z <= 51; z++) {
    const maxHalfW = getHalfWidth(z);
    for (let x = 4; x <= 51; x++) {
      const dx = Math.abs(x - 28);
      if (dx > maxHalfW) continue;

      const rearZ = getRearZ(dx);
      if (z > rearZ) continue;

      const normW = Math.max(1, maxHalfW);
      const v = dx / normW; // 0 at spine, 1 at edge
      const u = (z - 3) / 45; // 0 at prow, 1 at rear

      // Calculate lower belly surface
      const bellyDip = 5 * Math.max(0, 1 - Math.pow((z - 26) / 9, 2));
      const bellyCenter = 19 - bellyDip;
      const yBot = Math.round(19 - (19 - bellyCenter) * (1 - Math.pow(v, 1.4)));

      // Calculate upper dorsal surface
      const spineArch = 7 * Math.max(0, 1 - Math.pow((z - 24) / 16, 2)) +
                        3 * Math.max(0, 1 - Math.pow((z - 26) / 5, 2));
      const spineTop = 21 + spineArch;
      const yTop = Math.round(20 + (spineTop - 20) * (1 - Math.pow(v, 1.6)));

      for (let y = yBot; y <= yTop; y++) {
        const isTop = (y === yTop);
        const isBottom = (y === yBot);

        // Underside Harvester Iris
        if (isBottom) {
          const distToBeam = Math.hypot(x - beamCenterX, z - beamCenterZ);
          if (distToBeam <= 3.2) {
            put(x, y, z, "minecraft:crying_obsidian");
          } else if (distToBeam <= 5.2) {
            put(x, y, z, "minecraft:sea_lantern");
          } else if (distToBeam <= 7.5) {
            put(x, y, z, (dx % 2 === 0) ? "minecraft:chiseled_polished_blackstone" : "minecraft:crying_obsidian");
          } else {
            put(x, y, z, "minecraft:polished_blackstone");
          }
          continue;
        }

        // Top Dorsal Carapace & Energy Conduits
        if (isTop) {
          // Central spine conduit
          if (dx <= 1 && z >= 6 && z <= 36) {
            if (z % 4 === 0) {
              put(x, y, z, "minecraft:sea_lantern");
            } else {
              put(x, y, z, "minecraft:crying_obsidian");
            }
          }
          // Chevron lateral power channels
          else if (Math.abs((z - 3) - 1.5 * dx) < 1.0 || Math.abs((z - 15) - 1.4 * dx) < 1.0) {
            put(x, y, z, "minecraft:crying_obsidian");
          }
          // Sensor organ nodes
          else if ((dx === 6 && (z === 20 || z === 32)) || (dx === 12 && z === 36)) {
            put(x, y, z, "minecraft:sculk_catalyst");
          }
          // Carapace armor plating
          else {
            if ((x + z) % 4 === 0) {
              put(x, y, z, "minecraft:chiseled_polished_blackstone");
            } else if ((x + z) % 2 === 0) {
              put(x, y, z, "minecraft:polished_blackstone_bricks");
            } else {
              put(x, y, z, "minecraft:deepslate_tiles");
            }
          }
          continue;
        }

        // Solid Hull Interior Fill
        if (dx === Math.round(maxHalfW)) {
          put(x, y, z, "minecraft:crying_obsidian");
        } else {
          put(x, y, z, "minecraft:polished_blackstone");
        }
      }
    }
  }

  // ==========================================
  // 6. INTERNAL COMMAND BRIDGE & HARVESTER CORE
  // ==========================================
  // Carve out interior room from x:24..32, y:19..24, z:22..32
  for (let z = 22; z <= 32; z++) {
    for (let x = 24; x <= 32; x++) {
      // Solid floor at y=18
      const distCenter = Math.hypot(x - 28, z - 26);
      if (distCenter <= 1.8) {
        put(x, 18, z, "minecraft:cyan_stained_glass"); // Glass aperture over tractor shaft
      } else if (distCenter <= 3.2) {
        put(x, 18, z, "minecraft:crying_obsidian");
      } else {
        put(x, 18, z, "minecraft:polished_blackstone_bricks");
      }

      // Air space inside the bridge
      for (let y = 19; y <= 24; y++) {
        put(x, y, z, "minecraft:air");
      }

      // Ceiling at y=25
      if (x === 28 && (z === 24 || z === 28)) {
        put(x, 25, z, "minecraft:sea_lantern");
      } else {
        put(x, 25, z, "minecraft:polished_blackstone_bricks");
      }
    }
  }

  // Forward panoramic viewport
  for (let x = 26; x <= 30; x++) {
    for (let y = 20; y <= 23; y++) {
      put(x, y, 21, "minecraft:tinted_glass");
    }
  }

  // Bridge control consoles & glowing alien pillars
  put(25, 19, 23, "minecraft:sculk_catalyst");
  put(31, 19, 23, "minecraft:sculk_catalyst");
  put(25, 20, 23, "minecraft:crying_obsidian");
  put(31, 20, 23, "minecraft:crying_obsidian");

  put(25, 19, 31, "minecraft:warped_stem[axis=y]");
  put(31, 19, 31, "minecraft:warped_stem[axis=y]");
  put(25, 20, 31, "minecraft:crying_obsidian");
  put(31, 20, 31, "minecraft:crying_obsidian");

  // ==========================================
  // 7. DORSAL BRIDGE SUPERSTRUCTURE & SPIRE
  // ==========================================
  for (let z = 23; z <= 29; z++) {
    for (let x = 25; x <= 31; x++) {
      const d = Math.hypot(x - 28, z - 26);
      if (d <= 3.2) {
        put(x, 26, z, "minecraft:crying_obsidian");
        if (d <= 2.2) {
          put(x, 27, z, "minecraft:tinted_glass");
          put(x, 28, z, "minecraft:tinted_glass");
        }
        if (d <= 1.2) {
          put(x, 29, z, "minecraft:crying_obsidian");
          put(x, 30, z, "minecraft:crying_obsidian");
        }
      }
    }
  }

  // Main Dorsal Sub-Space Spire
  put(28, 30, 26, "minecraft:beacon");
  put(28, 31, 26, "minecraft:sea_lantern");
  put(28, 32, 26, "minecraft:crying_obsidian");
  put(28, 33, 26, "minecraft:end_rod[facing=up]");

  // ==========================================
  // 8. THRUSTERS & REAR ENGINE EXHAUSTS
  // ==========================================
  const thrusters = [
    [28, 37, 20], // Center Main Thruster
    [16, 44, 20], // Left Wing Thruster
    [40, 44, 20]  // Right Wing Thruster
  ];

  for (const [tx, tz, ty] of thrusters) {
    for (let ox = -1; ox <= 1; ox++) {
      for (let oy = -1; oy <= 1; oy++) {
        const px = tx + ox;
        const py = ty + oy;
        if (ox === 0 && oy === 0) {
          // Thruster nozzle core
          put(px, py, tz, "minecraft:sea_lantern");
          put(px, py, tz + 1, "minecraft:cyan_stained_glass");
          put(px, py, tz + 2, "minecraft:light_blue_stained_glass");
        } else {
          // Cowling
          put(px, py, tz, "minecraft:polished_blackstone_bricks");
          put(px, py, tz + 1, "minecraft:crying_obsidian");
        }
      }
    }
  }

  // ==========================================
  // 9. FORWARD PROW MANDIBLES & WINGLET FINS
  // ==========================================
  // Prow Sensor Mandibles
  put(27, 21, 2, "minecraft:deepslate_tile_stairs[facing=south,half=bottom]");
  put(29, 21, 2, "minecraft:deepslate_tile_stairs[facing=south,half=bottom]");
  put(27, 21, 1, "minecraft:end_rod[facing=north]");
  put(29, 21, 1, "minecraft:end_rod[facing=north]");

  // Vertical Outrigger Stabilizer Fins
  for (let y = 21; y <= 25; y++) {
    put(10, y, 44, "minecraft:polished_blackstone_wall");
    put(10, y, 45, "minecraft:crying_obsidian");
    put(46, y, 44, "minecraft:polished_blackstone_wall");
    put(46, y, 45, "minecraft:crying_obsidian");
  }

  // ==========================================
  // 10. FLUSH GRID TO WORLD
  // ==========================================
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const block = grid.get((x << 16) | (y << 8) | z);
        if (block) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Alien Harvester",
    seatY: 6,
    anchors: {
      front: [28, 21, 0],
      tractor_entry: [28, 6, 26],
      bridge: [28, 19, 26]
    },
    interiors: [
      {
        min: [24, 19, 22],
        max: [32, 24, 32],
        kind: "bridge"
      }
    ]
  };
}

