export const envelope = [20, 16, 20];

export default function build(api) {
  const [W, H, D] = api.size;
  const SEAT_Y = 4;

  // Grid buffer for deterministic assembly
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  const setBlock = (x, y, z, block) => {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  };

  // Palette from theme and alien materials
  const bank = api.theme.ground?.bank || "minecraft:coarse_dirt";
  const scree = api.theme.ground?.scree || "minecraft:gravel";
  const plinth = api.theme.ground?.plinth || "minecraft:stone_bricks";
  const pavement = api.theme.ground?.pavement || "minecraft:dirt_path";
  const woodPlanks = api.theme.wood?.planks || "minecraft:oak_planks";
  const woodFence = api.theme.wood?.fence || "minecraft:oak_fence";
  const woodLog = api.theme.wood?.log || "minecraft:oak_log";

  // Precompute terrain height at seat offset
  const groundMap = Array.from({ length: W }, (_, x) =>
    Array.from({ length: D }, (_, z) =>
      Math.max(0, Math.min(H - 1, SEAT_Y + Math.round(api.heightAt(x, z))))
    )
  );

  // -------------------------------------------------------------
  // STEP 1: IMPACT CRATER & CHURNED RURAL SOIL
  // -------------------------------------------------------------
  const craterSurface = Array.from({ length: W }, () => new Array(D).fill(0));

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const bgY = groundMap[x][z];
      const dx = x - 10;

      // Skid furrow width profile along Z (skidded from south z=16 to north z=5)
      let rZ = 5.2;
      if (z > 10) {
        rZ = 5.2 - 2.0 * ((z - 10) / 6.0);
      } else if (z < 5) {
        rZ = 5.2 - 2.4 * ((5 - z) / 5.0);
      }
      const d = Math.abs(dx) / Math.max(0.1, rZ);

      let surfY = bgY;
      if (z >= 3 && z <= 17) {
        if (d < 0.75) {
          // Trench depression
          const depth = (1.0 - d / 0.75) * (z <= 9 ? 2.6 : 1.5);
          surfY = bgY - Math.round(depth);
        } else if (d <= 1.4) {
          // Upheaved ejecta berm
          const bermAngle = ((d - 0.75) / 0.65) * Math.PI;
          const bermH = Math.sin(bermAngle) * (z <= 9 ? 2.3 : 1.3);
          surfY = bgY + Math.round(bermH);
        }
      }

      surfY = Math.max(1, Math.min(H - 2, surfY));
      craterSurface[x][z] = surfY;

      // Fill soil column solidly down to base ground / seabed
      const fillMin = Math.max(0, Math.min(bgY - 3, surfY - 1));
      for (let y = 0; y <= surfY; y++) {
        if (y < fillMin) {
          setBlock(x, y, z, "minecraft:stone");
        } else if (y < surfY) {
          if (y < bgY - 1) {
            setBlock(x, y, z, plinth);
          } else {
            setBlock(x, y, z, (x + y + z) % 3 === 0 ? bank : "minecraft:dirt");
          }
        } else {
          // Surface material selection
          if (d < 0.65 && z <= 11) {
            // Impact core: scorched earth & vitrified rock
            const pr = api.random();
            if (pr < 0.35) setBlock(x, y, z, "minecraft:basalt[axis=y]");
            else if (pr < 0.55) setBlock(x, y, z, "minecraft:smooth_basalt");
            else if (pr < 0.75) setBlock(x, y, z, "minecraft:magma_block");
            else if (pr < 0.88) setBlock(x, y, z, "minecraft:crying_obsidian");
            else setBlock(x, y, z, "minecraft:coarse_dirt");
          } else if (d < 0.85) {
            // Trench floor
            const pr = api.random();
            if (pr < 0.40) setBlock(x, y, z, "minecraft:coarse_dirt");
            else if (pr < 0.70) setBlock(x, y, z, "minecraft:rooted_dirt");
            else if (pr < 0.85) setBlock(x, y, z, "minecraft:mud");
            else setBlock(x, y, z, scree);
          } else if (d <= 1.40) {
            // Upheaved berm with shattered farm fences and scattered hay
            const pr = api.random();
            if (pr < 0.35) setBlock(x, y, z, bank);
            else if (pr < 0.60) setBlock(x, y, z, "minecraft:coarse_dirt");
            else if (pr < 0.75) setBlock(x, y, z, "minecraft:rooted_dirt");
            else if (pr < 0.88) setBlock(x, y, z, woodPlanks);
            else setBlock(x, y, z, "minecraft:hay_block[axis=y]");
          } else {
            // Rural field border
            setBlock(x, y, z, (x * 7 + z * 13) % 5 === 0 ? bank : pavement);
          }
        }
      }
    }
  }

  // Farm debris and splintered fence posts on berm
  const debrisCoords = [
    [5, 14, woodFence], [6, 15, "minecraft:hay_block[axis=z]"],
    [14, 15, "minecraft:hay_block[axis=x]"], [15, 13, woodFence],
    [4, 8, woodFence], [15, 8, woodFence],
    [5, 5, "minecraft:hay_block[axis=y]"], [14, 5, woodPlanks],
    [9, 16, "minecraft:iron_bars"], [11, 16, "minecraft:chain[axis=y]"]
  ];

  for (const [dx, dz, block] of debrisCoords) {
    const sy = craterSurface[dx][dz];
    if (sy + 1 < H) {
      setBlock(dx, sy + 1, dz, block);
    }
  }

  // -------------------------------------------------------------
  // STEP 2: GLOWING ALIEN SURVEY PYLONS IN FIELD
  // -------------------------------------------------------------
  const pylons = [
    { x: 3, z: 4, light: "minecraft:pearlescent_froglight" },
    { x: 16, z: 14, light: "minecraft:ochre_froglight" }
  ];

  for (const p of pylons) {
    const sy = craterSurface[p.x][p.z];
    if (sy + 4 < H) {
      setBlock(p.x, sy + 1, p.z, "minecraft:polished_blackstone_wall");
      setBlock(p.x, sy + 2, p.z, "minecraft:end_rod[facing=up]");
      setBlock(p.x, sy + 3, p.z, p.light);
      setBlock(p.x, sy + 4, p.z, "minecraft:amethyst_cluster[facing=up]");
      // Creeping sculk veins around base
      for (const [vx, vz] of [[p.x + 1, p.z], [p.x - 1, p.z], [p.x, p.z + 1], [p.x, p.z - 1]]) {
        const vsy = craterSurface[vx][vz];
        if (vsy + 1 < H && !grid[vx][vsy + 1][vz]) {
          setBlock(vx, vsy + 1, vz, "minecraft:sculk_vein[up=true]");
        }
      }
    }
  }

  // -------------------------------------------------------------
  // STEP 3: ALIEN SCOUT CRAFT (CHITIN HULL, ENGINES, BREACH)
  // -------------------------------------------------------------
  // Scout center and rotated orthonormal basis
  // Pitch = 0.36 rad (nose embedded), Roll = 0.22 rad (starboard wing raised)
  const cx = 10.0;
  const cy = 7.6;
  const cz = 9.5;

  const R = [0.976, 0.202, -0.081];
  const U = [-0.218, 0.906, -0.362];
  const F = [0.0, -0.371, -0.928];

  for (let x = 1; x < W - 1; x++) {
    for (let y = 1; y < H - 1; y++) {
      for (let z = 1; z < D - 1; z++) {
        const dx = x - cx;
        const dy = y - cy;
        const dz = z - cz;

        const u = dx * R[0] + dy * R[1] + dz * R[2];
        const v = dx * U[0] + dy * U[1] + dz * U[2];
        const w = dx * F[0] + dy * F[1] + dz * F[2];

        // Hull length: -6.2 (engines) to +5.5 (nose tip)
        if (w < -6.2 || w > 5.5) continue;

        const tw = (w + 6.2) / 11.7; // [0, 1]
        // Predatory delta-manta half-width profile
        const W_hull = 6.0 * Math.sin(Math.PI * Math.pow(tw, 0.70)) * (0.60 + 0.40 * (1 - tw));

        if (Math.abs(u) > W_hull + 0.35) continue;

        const normW = Math.min(1.0, Math.abs(u) / Math.max(0.1, W_hull));
        const Rfuse = 1.95 * Math.sqrt(Math.max(0, 1 - Math.pow(w / 5.8, 2)));
        const Rwing = 0.58 * Math.sqrt(Math.max(0, 1 - normW * normW));
        const k = Math.exp(-1.6 * Math.pow(u / 2.2, 2));

        let Vtop = Rfuse * k + Rwing * (1 - k);
        let Vbot = -(Rfuse * 0.88 * k + Rwing * (1 - k));

        // Dorsal spine ridge
        if (Math.abs(u) < 0.95 && w > -5.5 && w < 2.5) {
          Vtop += 0.55 * (1 - Math.abs(u) / 0.95) * (1 - Math.abs(w + 1.5) / 4.2);
        }
        // Aft engine cowlings
        if (w < -4.2 && Math.abs(u) < 3.2) {
          Vtop += 0.45;
        }

        if (v < Vbot - 0.25 || v > Vtop + 0.25) continue;

        // --- CATASTROPHIC HULL BREACH ZONE (Starboard dorsal tear) ---
        const breachDist = Math.hypot((w + 0.3) / 2.6, (u - 1.5) / 1.8);
        const inBreach = breachDist < 1.0 && v > -0.4;

        if (inBreach) {
          // Jagged curled chitin spines along tear rim
          if (breachDist >= 0.78 && breachDist <= 1.15 && v > 0.3 && v < 1.9) {
            const tearMat = (y + x) % 3 === 0
              ? "minecraft:crying_obsidian"
              : ((x + z) % 2 === 0 ? "minecraft:purpur_pillar[axis=y]" : "minecraft:polished_blackstone");
            setBlock(x, y, z, tearMat);
          } else if (v <= 0.2) {
            // Exposed glowing biomechanical core
            if (Math.hypot(w + 0.4, u - 0.8) < 0.9) {
              // Core reactor heart
              if (v < -0.2) {
                setBlock(x, y, z, "minecraft:crying_obsidian");
              } else if (v === -0.1 || v === 0.0) {
                // Smoking soul campfire atop crying obsidian
                setBlock(x, y, z, "minecraft:soul_campfire[lit=true,facing=north]");
              } else {
                setBlock(x, y, z, "minecraft:pearlescent_froglight");
              }
            } else if (Math.hypot(w + 0.8, u - 1.8) < 0.8) {
              setBlock(x, y, z, "minecraft:amethyst_block");
            } else if (Math.hypot(w - 0.5, u - 0.3) < 0.8) {
              setBlock(x, y, z, "minecraft:sculk_catalyst");
            } else {
              setBlock(x, y, z, (x + z) % 2 === 0 ? "minecraft:warped_stem[axis=y]" : "minecraft:crying_obsidian");
            }
          }
          continue;
        }

        // --- INTACT CHITIN HULL & ENGINES ---
        // Aft thrusters
        if (w <= -4.6) {
          // Center main thruster
          if (Math.abs(u) <= 1.0 && v >= -0.6 && v <= 0.7) {
            if (w <= -5.5) {
              setBlock(x, y, z, "minecraft:pearlescent_froglight");
            } else {
              setBlock(x, y, z, "minecraft:polished_blackstone");
            }
            continue;
          }
          // Port thruster
          if (u >= -2.7 && u <= -1.3 && v >= -0.5 && v <= 0.5) {
            if (w <= -5.3) {
              setBlock(x, y, z, "minecraft:ochre_froglight");
            } else {
              setBlock(x, y, z, "minecraft:polished_blackstone_bricks");
            }
            continue;
          }
          // Starboard thruster (Blown-out & smoking)
          if (u >= 1.3 && u <= 2.7 && v >= -0.5 && v <= 0.5) {
            if (w <= -5.2) {
              setBlock(x, y, z, "minecraft:campfire[lit=true,facing=north]");
            } else {
              setBlock(x, y, z, (x + y) % 2 === 0 ? "minecraft:magma_block" : "minecraft:crying_obsidian");
            }
            continue;
          }
        }

        // Forward insectoid cockpit canopy
        if (w >= 2.4 && w <= 4.2 && Math.abs(u) <= 1.15 && v >= 0.25 && v <= 1.25) {
          setBlock(x, y, z, "minecraft:tinted_glass");
          continue;
        }

        // Hull plating: Dorsal vs Ventral
        if (v >= 0.0) {
          // Dorsal chitin shell
          if (Math.abs(u) < 0.9) {
            // Central dorsal spine
            setBlock(x, y, z, (z % 2 === 0) ? "minecraft:purpur_pillar[axis=z]" : "minecraft:crying_obsidian");
          } else if (normW > 0.85) {
            // Outer wing edge
            setBlock(x, y, z, "minecraft:polished_blackstone");
          } else {
            // Wing plating with sculk & purpur banding
            const pattern = Math.floor(Math.abs(u) * 1.5 + w * 0.8);
            if (pattern % 3 === 0) {
              setBlock(x, y, z, "minecraft:purpur_block");
            } else if (pattern % 3 === 1) {
              setBlock(x, y, z, "minecraft:polished_blackstone_bricks");
            } else {
              setBlock(x, y, z, "minecraft:sculk");
            }
          }
        } else {
          // Ventral underbelly
          if (normW > 0.8) {
            setBlock(x, y, z, "minecraft:polished_blackstone");
          } else {
            setBlock(x, y, z, (x + z) % 3 === 0 ? "minecraft:smooth_basalt" : "minecraft:crying_obsidian");
          }
        }
      }
    }
  }

  // Raised starboard winglet fin & sensor horn
  const wingletCoords = [
    [15, 9, 10, "minecraft:purpur_block"],
    [15, 10, 10, "minecraft:polished_blackstone_wall"],
    [15, 11, 10, "minecraft:end_rod[facing=up]"],
    [10, 4, 3, "minecraft:crying_obsidian"],
    [10, 4, 2, "minecraft:end_rod[facing=north]"]
  ];

  for (const [wx, wy, wz, block] of wingletCoords) {
    setBlock(wx, wy, wz, block);
  }

  // -------------------------------------------------------------
  // STEP 4: GROUND CONFORMANCE & AIR GAP SEALING
  // -------------------------------------------------------------
  // Guarantee every occupied column reaches solid down to heightAt
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let minY = -1;
      for (let y = 0; y < H; y++) {
        if (grid[x][y][z] !== null) {
          minY = y;
          break;
        }
      }

      const bgY = groundMap[x][z];
      if (minY !== -1) {
        // Fill downwards if floating above ground
        if (minY > bgY) {
          for (let y = bgY; y < minY; y++) {
            grid[x][y][z] = y <= bgY ? plinth : (y % 2 === 0 ? bank : "minecraft:dirt");
          }
        }
        // Fill down to seat foundation (y=0)
        for (let y = 0; y < bgY; y++) {
          if (grid[x][y][z] === null) {
            grid[x][y][z] = y <= 2 ? "minecraft:stone" : "minecraft:dirt";
          }
        }
      } else {
        // Perimeter ground skirt
        for (let y = 0; y <= bgY; y++) {
          grid[x][y][z] = y <= 2 ? "minecraft:stone" : (y === bgY ? pavement : "minecraft:dirt");
        }
      }
    }
  }

  // -------------------------------------------------------------
  // STEP 5: EMIT BLOCKS DETERMINISTICALLY
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const b = grid[x][y][z];
        if (b !== null) {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "crashed_scout",
    seatY: SEAT_Y,
    anchors: {
      front: [10, 2, 0],
      impact: [10, 4, 6],
      breach: [11, 8, 9],
      engines: [10, 10, 15]
    }
  };
}

